[InitializeOnLoad] public static class TerrainLookStudy {
const string Root="Assets/CityForge/Art/Environment/TerrainLookStudy/";
const string Source="Assets/CityForge/Art/Environment/ObjectsWoodlandStudy/";
const string Work="/Users/joelinstrum/Documents/Codex/2026-10-08/tre/work/";
const string Output="/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/";
static Camera camera;static UnityEngine.SceneManagement.Scene scene;static double next;static int stage;static Color[] coverage,variation;static Transform woodland;
static TerrainLookStudy(){EditorApplication.update+=Tick;}
static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isPlaying)return;try{if(File.Exists(Work+"terrain-look")){File.Delete(Work+"terrain-look");Run();}if(next>0&&EditorApplication.timeSinceStartup>=next){next=0;if(stage==1){Capture("TerrainLook_1_Lighting");Ground();stage=2;next=EditorApplication.timeSinceStartup+4;}else if(stage==2){Capture("TerrainLook_2_Ground");Edges();stage=3;next=EditorApplication.timeSinceStartup+4;}else if(stage==3){Capture("TerrainLook_Zoom1");var rig=camera.GetComponent<CityForgeCameraController>();rig.SetZoomLevel(2);rig.ApplyPose();Capture("TerrainLook_Overview");rig.SetZoomLevel(1);rig.ApplyPose();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"TerrainLookZoom1.unity");Debug.Log("TERRAIN LOOK COMPLETE: lighting, ground variation and woodland edges saved");}}}catch(Exception e){next=0;Debug.LogException(e);}}
static float N(float x,float z,float scale)=>Mathf.PerlinNoise(x/scale+31,z/scale+59);
static float PathX(float z)=>112+18*Mathf.Sin(z*.026f)+.12f*(z-128);
static Vector3 Normal(float x,float z)=>new Vector3((HillsValleyStudy.Height(x-1,z)-HillsValleyStudy.Height(x+1,z))*.5f,1,(HillsValleyStudy.Height(x,z-1)-HillsValleyStudy.Height(x,z+1))*.5f).normalized;
static T Save<T>(T item,string path) where T:UnityEngine.Object{var old=AssetDatabase.LoadMainAssetAtPath(path);if(old){EditorUtility.CopySerialized(item,old);UnityEngine.Object.DestroyImmediate(item);return (T)old;}AssetDatabase.CreateAsset(item,path);return item;}
[MenuItem("CityForge/Ground Study/Refine Lighting Ground and Woodland Edges")]
public static void Run(){Directory.CreateDirectory(Root);scene=EditorSceneManager.OpenScene(Source+"ObjectsWoodlandZoom1.unity",OpenSceneMode.Single);camera=UnityEngine.Object.FindFirstObjectByType<Camera>();var rig=camera.GetComponent<CityForgeCameraController>();rig.FrameArea(2048,120,new Vector3(128,0,128));typeof(CityForgeCameraController).GetField("focus",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(rig,new Vector3(128,18,128));rig.SetZoomLevel(1);rig.ApplyPose();Capture("TerrainLook_Before");woodland=scene.GetRootGameObjects().First(g=>g.name.StartsWith("MapMagic generated woodland")).transform;var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);foreach(Transform obj in woodland){var pos=obj.position;pos.y=terrain.SampleHeight(pos);obj.position=pos;}
var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);sun.intensity=1.55f;sun.color=new Color(1,.97f,.91f);sun.transform.rotation=Quaternion.Euler(57,222,0);sun.shadowStrength=.48f;sun.shadows=LightShadows.Soft;sun.shadowBias=.035f;sun.shadowNormalBias=.25f;var additional=sun.GetUniversalAdditionalLightData();additional.softShadowQuality=SoftShadowQuality.High;
new GameObject("Soft summer sky fill").AddComponent<TerrainPresentationLighting>().Apply();RenderSettings.fog=false;RenderSettings.sun=sun;
var volume=UnityEngine.Object.FindFirstObjectByType<Volume>();var profile=UnityEngine.Object.Instantiate(volume.sharedProfile);profile.name="Soft summer terrain lighting";if(!profile.TryGet<ColorAdjustments>(out var adjust))adjust=profile.Add<ColorAdjustments>(true);adjust.postExposure.Override(-.12f);adjust.contrast.Override(3);adjust.saturation.Override(-10);if(!profile.TryGet<WhiteBalance>(out var balance))balance=profile.Add<WhiteBalance>(true);balance.temperature.Override(2);volume.sharedProfile=Save(profile,Root+"Lighting.asset");stage=1;next=EditorApplication.timeSinceStartup+4;Debug.Log("TERRAIN LOOK lighting prepared");}
static Texture2D Mask(string name,Color[] pixels){var tex=new Texture2D(512,512,TextureFormat.RGB24,false,true);tex.SetPixels(pixels);tex.Apply();var path=Root+name+".png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.sRGBTexture=false;importer.wrapMode=TextureWrapMode.Clamp;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
static void Ground(){var read=new Texture2D(2,2,TextureFormat.RGB24,false,true);read.LoadImage(File.ReadAllBytes(Source+"GroundCoverage.png"));coverage=read.GetPixels();UnityEngine.Object.DestroyImmediate(read);variation=new Color[512*512];var stones=woodland.Cast<Transform>().Where(t=>t.name.StartsWith("Stone")).ToArray();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);Vector3 toSun=-sun.transform.forward;
for(int z=0;z<512;z++)for(int x=0;x<512;x++){int i=z*512+x;float wx=x*.5f,wz=z*.5f;var normal=Normal(wx,wz);float slope=Vector3.Angle(normal,Vector3.up);float wood=coverage[i].r;float meadow=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.2f,.65f,wood));float sunward=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.45f,.95f,Vector3.Dot(normal,toSun)));float dry=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.42f,.7f,N(wx+52,wz-31,33)))*(.24f+.42f*sunward)*meadow;float edge=1-Mathf.Abs(wood-.35f)*2.8f;float bare=Mathf.Clamp01(edge)*Mathf.SmoothStep(0,1,Mathf.InverseLerp(.5f,.7f,N(wx,wz,5)))*.25f;
float rock=0;foreach(var stone in stones){float d=Vector2.Distance(new Vector2(wx,wz),new Vector2(stone.position.x,stone.position.z));float radius=2.3f+stone.localScale.x*2;rock=Mathf.Max(rock,(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(radius*.3f,radius,d)))*.65f);}
rock=Mathf.Max(rock,Mathf.SmoothStep(0,1,Mathf.InverseLerp(19,33,slope))*Mathf.SmoothStep(0,1,Mathf.InverseLerp(.5f,.7f,N(wx,wz,11)))*.45f);float path=1-coverage[i].g;variation[i]=new Color(dry*path,bare*path,rock*path,1);}
var material=new Material(scene.GetRootGameObjects().First(g=>g.name.StartsWith("Ground with meadow")).GetComponent<Renderer>().sharedMaterial);material.shader=Shader.Find("CityForge/Terrain Look Study");material.SetTexture("_Variation",Mask("TerrainVariation",variation));material.SetTexture("_DryGrass",AssetDatabase.LoadAssetAtPath<Texture2D>(GroundZoom1Study.Art+"Forest4_Albedo.png"));material.SetTexture("_Stone",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/MapMagic/Demo/Stones/Textures/Stones.tif"));material=Save(material,Root+"Ground.mat");scene.GetRootGameObjects().First(g=>g.name.StartsWith("Ground with meadow")).GetComponent<Renderer>().sharedMaterial=material;
var stoneMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));stoneMat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/MapMagic/Demo/Stones/Textures/Stones.tif"));stoneMat.SetColor("_BaseColor",new Color(.78f,.79f,.74f));stoneMat.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/MapMagic/Demo/Stones/Textures/Stones_n.tif"));stoneMat.SetFloat("_BumpScale",.55f);stoneMat.EnableKeyword("_NORMALMAP");stoneMat.SetFloat("_Smoothness",.08f);stoneMat=Save(stoneMat,Root+"Stone.mat");foreach(var stone in stones)foreach(var r in stone.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>stoneMat).ToArray();
var grass=scene.GetRootGameObjects().First(g=>g.name.StartsWith("Short meadow grass"));var gm=new Material(material);gm.SetFloat("_SurfaceScale",.92f);grass.GetComponent<Renderer>().sharedMaterial=Save(gm,Root+"Grass.mat");var mesh=UnityEngine.Object.Instantiate(grass.GetComponent<MeshFilter>().sharedMesh);var verts=mesh.vertices;var tris=mesh.triangles;var filtered=new List<int>();for(int q=0;q<tris.Length;q+=3){var p=(verts[tris[q]]+verts[tris[q+1]])*.5f;int i=Mathf.Clamp((int)(p.z*2),0,511)*512+Mathf.Clamp((int)(p.x*2),0,511);if(variation[i].b>.2f||variation[i].g>.18f)continue;filtered.Add(tris[q]);filtered.Add(tris[q+1]);filtered.Add(tris[q+2]);}mesh.SetTriangles(filtered,0);grass.GetComponent<MeshFilter>().sharedMesh=Save(mesh,Root+"MeadowGrass.asset");Debug.Log("TERRAIN LOOK ground prepared");}
static GameObject[] Shrubs(){var results=new List<GameObject>();int[] types={3,6,8};for(int k=0;k<types.Length;k++){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CityForge/Art/Environment/ForestTreesTrial/low_poly_"+types[k]+".prefab");var mf=source.GetComponentInChildren<MeshFilter>();var renderer=mf.GetComponent<Renderer>();var original=mf.sharedMesh;var indices=new List<int>();for(int s=0;s<original.subMeshCount;s++)if(!renderer.sharedMaterials[s].name.StartsWith("Bark"))indices.AddRange(original.GetTriangles(s));var map=new Dictionary<int,int>();var vertices=new List<Vector3>();var normals=new List<Vector3>();var tri=new List<int>();var sourceVerts=original.vertices;var sourceNormals=original.normals;foreach(int index in indices){if(!map.TryGetValue(index,out int mapped)){mapped=vertices.Count;map[index]=mapped;vertices.Add(sourceVerts[index]*100);normals.Add(sourceNormals[index]);}tri.Add(mapped);}var b=new Bounds(vertices[0],Vector3.zero);foreach(var v in vertices)b.Encapsulate(v);float factor=2.4f/Mathf.Max(b.size.x,b.size.z);for(int i=0;i<vertices.Count;i++){var p=vertices[i]-new Vector3(b.center.x,b.min.y,b.center.z);p*=factor;p.y*=.72f;vertices[i]=p;}var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateBounds();mesh=Save(mesh,Root+"Shrub"+k+".asset");var mat=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/CityForge/Art/Environment/ForestTreesTrial/Leaves.mat"));mat.SetColor("_BaseColor",new[]{new Color(.25f,.40f,.13f),new Color(.33f,.43f,.15f),new Color(.29f,.43f,.18f)}[k]);mat=Save(mat,Root+"Shrub"+k+".mat");var go=new GameObject("Leafy woodland edge shrub "+k);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=mat;results.Add(PrefabUtility.SaveAsPrefabAsset(go,Root+"Shrub"+k+".prefab"));UnityEngine.Object.DestroyImmediate(go);}return results.ToArray();}
static T Add<T>(Graph graph,T gen,float x,float y) where T:Generator{gen.id=Den.Tools.Id.Generate();if(gen is IMultiInlet multi)foreach(IUnit inlet in multi.Inlets()){inlet.SetGen(gen);inlet.Id=Den.Tools.Id.Generate();}gen.guiPosition=new Vector2(x,y);graph.Add(gen);return gen;}
static void Edges(){var shrubs=Shrubs();var map=ScriptableObject.CreateInstance<MatrixAsset>();map.source=MatrixAsset.Source.New;map.matrix=new Matrix(new CoordRect(0,0,256,256));float total=0;for(int z=0;z<256;z++)for(int x=0;x<256;x++){int i=(z*2)*512+x*2;float cover=coverage[i].r;float edge=.30f+.70f*Mathf.Clamp01(1-Mathf.Abs(cover-.3f)*2.5f);float near=0;foreach(Transform tree in woodland){if(tree.name.StartsWith("Stone")||tree.localScale.x<.4f)continue;float d=Vector2.Distance(new Vector2(x,z),new Vector2(tree.position.x,tree.position.z));near=Mathf.Max(near,1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(5,20,d)));}float path=Mathf.SmoothStep(0,1,Mathf.InverseLerp(4,8,Mathf.Abs(x-PathX(z))));float slope=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(24,38,Vector3.Angle(Normal(x,z),Vector3.up)));float value=edge*near*path*slope*(1-variation[i].b)*Mathf.SmoothStep(0,1,Mathf.InverseLerp(.38f,.65f,N(x+17,z+12,9)));map.matrix.arr[z*256+x]=value;total+=value;}map=Save(map,Root+"WoodlandEdgeSuitability.asset");
var graph=ScriptableObject.CreateInstance<Graph>();graph.random=new Noise(719534,32768);var import=Add(graph,new Import200{matrixAsset=map},0,0);var scatter=Add(graph,new Scatter200{density=95000,seed=15832,uniformity=.08f,relax=.3f},210,0);var mask=Add(graph,new MapMagic.Nodes.ObjectsGenerators.Mask200{seed=81326},420,0);graph.Link(scatter,mask.srcIn);graph.Link(import,mask.maskIn);var adjust=Add(graph,new Adjust200{seed=61783,useRandom=true,rotation=new Vector2(0,360),scale=new Vector2(.45f,1.35f)},630,0);graph.Link(mask,adjust.input);var output=Add(graph,new ObjectsOutput{prefabs=shrubs,seed=21347,posSettings=new PositioningSettings{objHeight=false,relativeHeight=true,useScale=true,useRotation=true,rotateYonly=true}},840,0);graph.Link(adjust,output);graph=Save(graph,Root+"WoodlandEdgesGraph.asset");AssetDatabase.SaveAssets();var data=new MapMagic.Products.TileData{area=new Area(new Vector2D(0,0),new Vector2D(256,256),256,0),globals=new Globals{height=80},random=graph.random};data.heights=new MatrixWorld(data.area.full.rect,data.area.full.worldPos,data.area.full.worldSize,80);for(int z=0;z<256;z++)for(int x=0;x<256;x++)data.heights.arr[z*256+x]=HillsValleyStudy.Height(x*256f/255,z*256f/255)/80;var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);var stop=new StopToken();graph.Prepare(data,terrain);graph.Generate(data,stop);graph.Finalize(data,stop);var applied=data.ApplyOfType<ObjectsOutput.ApplyObjectsData>();if(applied==null)throw new Exception("Missing woodland edge output");var root=new GameObject("MapMagic generated low woodland edge vegetation");int count=0;float maxError=0;for(int p=0;p<applied.prototypes.Length;p++)foreach(var tr in applied.transitions[p]){var go=(GameObject)PrefabUtility.InstantiatePrefab(applied.prototypes[p].prefab,scene);go.transform.SetParent(root.transform,false);go.transform.position=new Vector3(tr.pos.x,terrain.SampleHeight(tr.pos),tr.pos.z);go.transform.rotation=tr.rotation;go.transform.localScale=tr.scale;maxError=Mathf.Max(maxError,Mathf.Abs(go.transform.position.y-terrain.SampleHeight(go.transform.position)));count++;}File.WriteAllText(Work+"terrain-look-result.txt",$"Added {count} low leafy shrubs using saved MapMagic edge graph. Maximum terrain grounding error: {maxError:F3}m.\n");Debug.Log($"TERRAIN LOOK woodland edges: {count} shrubs; max grounding error {maxError:F3}m");}
static void Capture(string name){var rt=new RenderTexture(3840,2160,24);rt.Create();var previous=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var tex=new Texture2D(3840,2160,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,3840,2160),0,0);tex.Apply();File.WriteAllBytes(Output+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}}
